import{_ as l,a0 as o,w as d,s as c,ao as p,I as t,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 上用 strace 來理解系統調用 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 strace 來理解系統調用 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 strace 來理解系統調用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 strace 來理解系統調用 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191025 Understanding system calls on Linux with strace","title":"在 Linux 上用 strace 來理解系統調用","tag":"201911","desc":""},"relativePath":"201911/20191025 Understanding system calls on Linux with strace.md","filePath":"[post].md"}'),r={name:"201911/20191025 Understanding system calls on Linux with strace.md"};function h(g,s,u,b,k,f){const a=o("Link");return d(),c("div",null,[s[18]||(s[18]=p('<h1 id="在-linux-上用-strace-來理解系統調用" tabindex="-1">在 Linux 上用 strace 來理解系統調用 <a class="header-anchor" href="#在-linux-上用-strace-來理解系統調用" aria-label="Permalink to “在 Linux 上用 strace 來理解系統調用”">​</a></h1><blockquote><p>使用 strace 跟蹤用户進程和 Linux 內核之間的交互。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/yearbook-haff-rx-linux-file-lead_0.png?itok=-i0NNfDC" alt="Hand putting a Linux file folder into a drawer" title="Hand putting a Linux file folder into a drawer"></p><p><ruby>系統調用<rt>system call</rt></ruby>是程序從內核請求服務的一種編程方式，而 <code>strace</code> 是一個功能強大的工具，可讓你跟蹤用户進程與 Linux 內核之間的交互。</p><p>要了解操作系統的工作原理，首先需要了解系統調用的工作原理。操作系統的主要功能之一是為用户程序提供抽象機制。</p><p>操作系統可以大致分為兩種模式：</p><ul><li>內核模式：操作系統內核使用的一種強大的特權模式</li><li>用户模式：大多數用户應用程序運行的地方    用户大多使用命令列實用程序和圖形用户界面（GUI）來執行日常任務。系統調用在後台靜默運行，與內核交互以完成工作。</li></ul>',7)),t("p",null,[s[1]||(s[1]=e("系統調用與函數調用非常相似，這意味着它們都接受並處理參數然後返回值。唯一的區別是系統調用進入內核，而函數調用不進入。從用户空間切換到內核空間是使用特殊的 ",-1)),n(a,{href:"https://en.wikipedia.org/wiki/Trap_(computing)"},{default:i(()=>[...s[0]||(s[0]=[e("trap",-1)])]),_:1}),s[2]||(s[2]=e(" 機制完成的。",-1))]),s[19]||(s[19]=p(`<p>通過使用系統庫（在 Linux 系統上又稱為 glibc），大部分系統調用對用户隱藏了。儘管系統調用本質上是通用的，但是發出系統調用的機制在很大程度上取決於機器（架構）。</p><p>本文通過使用一些常規命令並使用 <code>strace</code> 分析每個命令進行的系統調用來探索一些實際示例。這些示例使用 Red Hat Enterprise Linux，但是這些命令運行在其他 Linux 發行版上應該也是相同的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# cat /etc/redhat-release</span></span>
<span class="line"><span>Red Hat Enterprise Linux Server release 7.7 (Maipo)</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span>
<span class="line"><span>[root@sandbox ~]# uname -r</span></span>
<span class="line"><span>3.10.0-1062.el7.x86_64</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span></code></pre></div><p>首先，確保在系統上安裝了必需的工具。你可以使用下面的 <code>rpm</code> 命令來驗證是否安裝了 <code>strace</code>。如果安裝了，則可以使用 <code>-V</code> 選項檢查 <code>strace</code> 實用程序的版本號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# rpm -qa | grep -i strace</span></span>
<span class="line"><span>strace-4.12-9.el7.x86_64</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span>
<span class="line"><span>[root@sandbox ~]# strace -V</span></span>
<span class="line"><span>strace -- version 4.12</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span></code></pre></div><p>如果沒有安裝，運行命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum install strace</span></span></code></pre></div><p>出於本示例的目的，在 <code>/tmp</code> 中創建一個測試目錄，並使用 <code>touch</code> 命令創建兩個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# cd /tmp/</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span>
<span class="line"><span>[root@sandbox tmp]# mkdir testdir</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span>
<span class="line"><span>[root@sandbox tmp]# touch testdir/file1</span></span>
<span class="line"><span>[root@sandbox tmp]# touch testdir/file2</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>（我使用 <code>/tmp</code> 目錄是因為每個人都可以訪問它，但是你可以根據需要選擇另一個目錄。）</p><p>在 <code>testdir</code> 目錄下使用 <code>ls</code> 命令驗證該文件已經創建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# ls testdir/</span></span>
<span class="line"><span>file1  file2</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>你可能每天都在使用 <code>ls</code> 命令，而沒有意識到系統調用在其下面發揮的作用。抽象地來説，該命令的工作方式如下：</p><blockquote><p>命令列工具 -&gt; 從系統庫（glibc）調用函數 -&gt; 調用系統調用</p></blockquote><p><code>ls</code> 命令內部從 Linux 上的系統庫（即 glibc）調用函數。這些庫去調用完成大部分工作的系統調用。</p><p>如果你想知道從 glibc 庫中調用了哪些函數，請使用 <code>ltrace</code> 命令，然後跟上常規的 <code>ls testdir/</code>命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ltrace ls testdir/</span></span></code></pre></div><p>如果沒有安裝 <code>ltrace</code>，鍵入如下命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum install ltrace</span></span></code></pre></div><p>大量的輸出會被堆到屏幕上；不必擔心，只需繼續就行。<code>ltrace</code> 命令輸出中與該示例有關的一些重要庫函數包括：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>opendir(&quot;testdir/&quot;)                                  = { 3 }</span></span>
<span class="line"><span>readdir({ 3 })                                       = { 101879119, &quot;.&quot; }</span></span>
<span class="line"><span>readdir({ 3 })                                       = { 134, &quot;..&quot; }</span></span>
<span class="line"><span>readdir({ 3 })                                       = { 101879120, &quot;file1&quot; }</span></span>
<span class="line"><span>strlen(&quot;file1&quot;)                                      = 5</span></span>
<span class="line"><span>memcpy(0x1665be0, &quot;file1\\0&quot;, 6)                      = 0x1665be0</span></span>
<span class="line"><span>readdir({ 3 })                                       = { 101879122, &quot;file2&quot; }</span></span>
<span class="line"><span>strlen(&quot;file2&quot;)                                      = 5</span></span>
<span class="line"><span>memcpy(0x166dcb0, &quot;file2\\0&quot;, 6)                      = 0x166dcb0</span></span>
<span class="line"><span>readdir({ 3 })                                       = nil</span></span>
<span class="line"><span>closedir({ 3 })</span></span></code></pre></div><p>通過查看上面的輸出，你或許可以瞭解正在發生的事情。<code>opendir</code> 庫函數打開一個名為 <code>testdir</code> 的目錄，然後調用 <code>readdir</code> 函數，該函數讀取目錄的內容。最後，有一個對 <code>closedir</code> 函數的調用，該函數將關閉先前打開的目錄。現在請先忽略其他 <code>strlen</code> 和 <code>memcpy</code> 功能。</p><p>你可以看到正在調用哪些庫函數，但是本文將重點介紹由系統庫函數調用的系統調用。</p><p>與上述類似，要了解調用了哪些系統調用，只需將 <code>strace</code> 放在 <code>ls testdir</code> 命令之前，如下所示。 再次，一堆亂碼丟到了你的屏幕上，你可以按照以下步驟進行操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# strace ls testdir/</span></span>
<span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span>
<span class="line"><span>brk(NULL)                               = 0x1f12000</span></span>
<span class="line"><span>&lt;&lt;&lt; truncated strace output &gt;&gt;&gt;</span></span>
<span class="line"><span>write(1, &quot;file1  file2\\n&quot;, 13file1  file2</span></span>
<span class="line"><span>)          = 13</span></span>
<span class="line"><span>close(1)                                = 0</span></span>
<span class="line"><span>munmap(0x7fd002c8d000, 4096)            = 0</span></span>
<span class="line"><span>close(2)                                = 0</span></span>
<span class="line"><span>exit_group(0)                           = ?</span></span>
<span class="line"><span>+++ exited with 0 +++</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>運行 <code>strace</code> 命令後屏幕上的輸出就是運行 <code>ls</code> 命令的系統調用。每個系統調用都為操作系統提供了特定的用途，可以將它們大致分為以下幾個部分：</p><ul><li>進程管理系統調用</li><li>文件管理系統調用</li><li>目錄和文件系統管理系統調用</li><li>其他系統調用</li></ul><p>分析顯示到屏幕上的信息的一種更簡單的方法是使用 <code>strace</code> 方便的 <code>-o</code> 標誌將輸出記錄到文件中。在 <code>-o</code> 標誌後添加一個合適的文件名，然後再次運行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# strace -o trace.log ls testdir/</span></span>
<span class="line"><span>file1  file2</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>這次，沒有任何輸出干擾屏幕顯示，<code>ls</code> 命令如預期般工作，顯示了文件名並將所有輸出記錄到文件 <code>trace.log</code> 中。僅僅是一個簡單的 <code>ls</code> 命令，該文件就有近 100 行內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# ls -l trace.log</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 7809 Oct 12 13:52 trace.log</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span>
<span class="line"><span>[root@sandbox tmp]# wc -l trace.log</span></span>
<span class="line"><span>114 trace.log</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>讓我們看一下這個示例的 <code>trace.log</code> 文件的第一行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span></code></pre></div><ul><li>該行的第一個單詞 <code>execve</code> 是正在執行的系統調用的名稱。</li><li>括號內的文本是提供給該系統調用的參數。</li><li>符號 <code>=</code> 後的數字（在這種情況下為 <code>0</code>）是 <code>execve</code> 系統調用的返回值。</li></ul><p>現在的輸出似乎還不太嚇人，對吧。你可以應用相同的邏輯來理解其他行。</p><p>現在，將關注點集中在你調用的單個命令上，即 <code>ls testdir</code>。你知道命令 <code>ls</code> 使用的目錄名稱，那麼為什麼不在 <code>trace.log</code> 文件中使用 <code>grep</code> 查找 <code>testdir</code> 並查看得到的結果呢？讓我們詳細查看一下結果的每一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# grep testdir trace.log</span></span>
<span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span>
<span class="line"><span>stat(&quot;testdir/&quot;, {st_mode=S_IFDIR|0755, st_size=32, ...}) = 0</span></span>
<span class="line"><span>openat(AT_FDCWD, &quot;testdir/&quot;, O_RDONLY|O_NONBLOCK|O_DIRECTORY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>回顧一下上面對 <code>execve</code> 的分析，你能説一下這個系統調用的作用嗎？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span></code></pre></div><p>你無需記住所有系統調用或它們所做的事情，因為你可以在需要時參考文檔。手冊頁可以解救你！在運行 <code>man</code> 命令之前，請確保已安裝以下軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# rpm -qa | grep -i man-pages</span></span>
<span class="line"><span>man-pages-3.53-5.el7.noarch</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>請記住，你需要在 <code>man</code> 命令和系統調用名稱之間添加 <code>2</code>。如果使用 <code>man man</code> 閲讀 <code>man</code> 命令的手冊頁，你會看到第 2 節是為系統調用保留的。同樣，如果你需要有關庫函數的信息，則需要在 <code>man</code> 和庫函數名稱之間添加一個 <code>3</code>。</p><p>以下是手冊的章節編號及其包含的頁面類型：</p><ul><li><code>1</code>：可執行的程序或 shell 命令</li><li><code>2</code>：系統調用（由內核提供的函數）</li><li><code>3</code>：庫調用（在程序的庫內的函數）</li><li><code>4</code>：特殊文件（通常出現在 <code>/dev</code>）</li></ul><p>使用系統調用名稱運行以下 <code>man</code> 命令以查看該系統調用的文檔：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man 2 execve</span></span></code></pre></div><p>按照 <code>execve</code> 手冊頁，這將執行在參數中傳遞的程序（在本例中為 <code>ls</code>）。可以為 <code>ls</code> 提供其他參數，例如本例中的 <code>testdir</code>。因此，此係統調用僅以 <code>testdir</code> 作為參數運行 <code>ls</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>execve - execute program</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DESCRIPTION</span></span>
<span class="line"><span>       execve()  executes  the  program  pointed to by filename</span></span></code></pre></div><p>下一個系統調用，名為 <code>stat</code>，它使用 <code>testdir</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stat(&quot;testdir/&quot;, {st_mode=S_IFDIR|0755, st_size=32, ...}) = 0</span></span></code></pre></div><p>使用 <code>man 2 stat</code> 訪問該文檔。<code>stat</code> 是獲取文件狀態的系統調用，請記住，Linux 中的一切都是文件，包括目錄。</p><p>接下來，<code>openat</code> 系統調用將打開 <code>testdir</code>。密切注意返回的 <code>3</code>。這是一個文件描述符，將在以後的系統調用中使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openat(AT_FDCWD, &quot;testdir/&quot;, O_RDONLY|O_NONBLOCK|O_DIRECTORY|O_CLOEXEC) = 3</span></span></code></pre></div><p>到現在為止一切都挺好。現在，打開 <code>trace.log</code> 文件，並轉到 <code>openat</code> 系統調用之後的行。你會看到 <code>getdents</code> 系統調用被調用，該調用完成了執行 <code>ls testdir</code> 命令所需的大部分操作。現在，從 <code>trace.log</code> 文件中用 <code>grep</code> 獲取 <code>getdents</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# grep getdents trace.log</span></span>
<span class="line"><span>getdents(3, /* 4 entries */, 32768)     = 112</span></span>
<span class="line"><span>getdents(3, /* 0 entries */, 32768)     = 0</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p><code>getdents</code> 的手冊頁將其描述為 “獲取目錄項”，這就是你要執行的操作。注意，<code>getdents</code> 的參數是 <code>3</code>，這是來自上面 <code>openat</code> 系統調用的文件描述符。</p><p>現在有了目錄列表，你需要一種在終端中顯示它的方法。因此，在日誌中用 <code>grep</code> 搜索另一個用於寫入終端的系統調用 <code>write</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# grep write trace.log</span></span>
<span class="line"><span>write(1, &quot;file1  file2\\n&quot;, 13)          = 13</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>在這些參數中，你可以看到將要顯示的文件名：<code>file1</code> 和 <code>file2</code>。關於第一個參數（<code>1</code>），請記住在 Linux 中，當運行任何進程時，默認情況下會為其打開三個文件描述符。以下是默認的文件描述符：</p><ul><li><code>0</code>：標準輸入</li><li><code>1</code>：標準輸出</li><li><code>2</code>：標準錯誤</li></ul><p>因此，<code>write</code> 系統調用將在標準顯示（就是這個終端，由 <code>1</code> 所標識的）上顯示 <code>file1</code> 和 <code>file2</code>。</p><p>現在你知道哪個系統調用完成了 <code>ls testdir/</code> 命令的大部分工作。但是在 <code>trace.log</code> 文件中其它的 100 多個系統調用呢？操作系統必須做很多內務處理才能運行一個進程，因此，你在該日誌文件中看到的很多內容都是進程初始化和清理。閲讀整個 <code>trace.log</code> 文件，並嘗試瞭解 <code>ls</code> 命令是怎麼工作起來的。</p><p>既然你知道了如何分析給定命令的系統調用，那麼就可以將該知識用於其他命令來了解正在執行哪些系統調用。<code>strace</code> 提供了許多有用的命令列標誌，使你更容易使用，下面將對其中一些進行描述。</p><p>默認情況下，<code>strace</code> 並不包含所有系統調用信息。但是，它有一個方便的 <code>-v</code> 冗餘選項，可以在每個系統調用中提供附加信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>strace -v ls testdir</span></span></code></pre></div><p>在運行 <code>strace</code> 命令時始終使用 <code>-f</code> 選項是一種好的作法。它允許 <code>strace</code> 對當前正在跟蹤的進程創建的任何子進程進行跟蹤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>strace -f ls testdir</span></span></code></pre></div><p>假設你只需要系統調用的名稱、運行的次數以及每個系統調用花費的時間百分比。你可以使用 <code>-c</code> 標誌來獲取這些統計信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>strace -c ls testdir/</span></span></code></pre></div><p>假設你想專注於特定的系統調用，例如專注於 <code>open</code> 系統調用，而忽略其餘部分。你可以使用<code>-e</code> 標誌跟上系統調用的名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# strace -e open ls testdir</span></span>
<span class="line"><span>open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libselinux.so.1&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libcap.so.2&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libacl.so.1&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libc.so.6&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libpcre.so.1&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libdl.so.2&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libattr.so.1&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib64/libpthread.so.0&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/usr/lib/locale/locale-archive&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>file1  file2</span></span>
<span class="line"><span>+++ exited with 0 +++</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>如果你想關注多個系統調用怎麼辦？不用擔心，你同樣可以使用 <code>-e</code> 命令列標誌，並用逗號分隔開兩個系統調用的名稱。例如，要查看 <code>write</code> 和 <code>getdents</code> 系統調用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# strace -e write,getdents ls testdir</span></span>
<span class="line"><span>getdents(3, /* 4 entries */, 32768)     = 112</span></span>
<span class="line"><span>getdents(3, /* 0 entries */, 32768)     = 0</span></span>
<span class="line"><span>write(1, &quot;file1  file2\\n&quot;, 13file1  file2</span></span>
<span class="line"><span>)          = 13</span></span>
<span class="line"><span>+++ exited with 0 +++</span></span>
<span class="line"><span>[root@sandbox tmp]#</span></span></code></pre></div><p>到目前為止，這些示例是明確地運行的命令進行了跟蹤。但是，要跟蹤已經運行並正在執行的命令又怎麼辦呢？例如，如果要跟蹤用來長時間運行進程的守護程序，該怎麼辦？為此，<code>strace</code> 提供了一個特殊的 <code>-p</code> 標誌，你可以向其提供進程 ID。</p><p>我們的示例不在守護程序上運行 <code>strace</code>，而是以 <code>cat</code> 命令為例，如果你將文件名作為參數，通常 <code>cat</code> 會顯示文件的內容。如果沒有給出參數，<code>cat</code> 命令會在終端上等待用户輸入文本。輸入文本後，它將重複給定的文本，直到用户按下 <code>Ctrl + C</code> 退出為止。</p><p>從一個終端運行 <code>cat</code> 命令；它會向你顯示一個提示，並等待在那裏（記住 <code>cat</code> 仍在運行且尚未退出）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# cat</span></span></code></pre></div><p>在另一個終端上，使用 <code>ps</code> 命令找到進程標識符（PID）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# ps -ef | grep cat</span></span>
<span class="line"><span>root      22443  20164  0 14:19 pts/0    00:00:00 cat</span></span>
<span class="line"><span>root      22482  20300  0 14:20 pts/1    00:00:00 grep --color=auto cat</span></span>
<span class="line"><span>[root@sandbox ~]#</span></span></code></pre></div><p>現在，使用 <code>-p</code> 標誌和 PID（在上面使用 <code>ps</code> 找到）對運行中的進程運行 <code>strace</code>。運行 <code>strace</code> 之後，其輸出説明了所接駁的進程的內容及其 PID。現在，<code>strace</code> 正在跟蹤 <code>cat</code> 命令進行的系統調用。看到的第一個系統調用是 <code>read</code>，它正在等待文件描述符 <code>0</code>（標準輸入，這是運行 <code>cat</code> 命令的終端）的輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# strace -p 22443</span></span>
<span class="line"><span>strace: Process 22443 attached</span></span>
<span class="line"><span>read(0,</span></span></code></pre></div><p>現在，返回到你運行 <code>cat</code> 命令的終端，並輸入一些文本。我出於演示目的輸入了 <code>x0x0</code>。注意 <code>cat</code> 是如何簡單地重複我輸入的內容的。因此，<code>x0x0</code> 出現了兩次。我輸入了第一個，第二個是 <code>cat</code> 命令重複的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox tmp]# cat</span></span>
<span class="line"><span>x0x0</span></span>
<span class="line"><span>x0x0</span></span></code></pre></div><p>返回到將 <code>strace</code> 接駁到 <code>cat</code> 進程的終端。現在你會看到兩個額外的系統調用：較早的 <code>read</code> 系統調用，現在在終端中讀取 <code>x0x0</code>，另一個為 <code>write</code>，它將 <code>x0x0</code> 寫回到終端，然後是再一個新的 <code>read</code>，正在等待從終端讀取。請注意，標準輸入（<code>0</code>）和標準輸出（<code>1</code>）都在同一終端中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]# strace -p 22443</span></span>
<span class="line"><span>strace: Process 22443 attached</span></span>
<span class="line"><span>read(0, &quot;x0x0\\n&quot;, 65536)                = 5</span></span>
<span class="line"><span>write(1, &quot;x0x0\\n&quot;, 5)                   = 5</span></span>
<span class="line"><span>read(0,</span></span></code></pre></div><p>想像一下，對守護進程運行 <code>strace</code> 以查看其在後台執行的所有操作時這有多大幫助。按下 <code>Ctrl + C</code> 殺死 <code>cat</code> 命令；由於該進程不再運行，因此這也會終止你的 <code>strace</code> 會話。</p><p>如果要查看所有的系統調用的時間戳，只需將 <code>-t</code> 選項與 <code>strace</code> 一起使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]#strace -t ls testdir/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>14:24:47 execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span>
<span class="line"><span>14:24:47 brk(NULL)                      = 0x1f07000</span></span>
<span class="line"><span>14:24:47 mmap(NULL, 4096, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) = 0x7f2530bc8000</span></span>
<span class="line"><span>14:24:47 access(&quot;/etc/ld.so.preload&quot;, R_OK) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>14:24:47 open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span></code></pre></div><p>如果你想知道兩次系統調用之間所花費的時間怎麼辦？<code>strace</code> 有一個方便的 <code>-r</code> 命令，該命令顯示執行每個系統調用所花費的時間。非常有用，不是嗎？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@sandbox ~]#strace -r ls testdir/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0.000000 execve(&quot;/usr/bin/ls&quot;, [&quot;ls&quot;, &quot;testdir/&quot;], [/* 40 vars */]) = 0</span></span>
<span class="line"><span>0.000368 brk(NULL)                 = 0x1966000</span></span>
<span class="line"><span>0.000073 mmap(NULL, 4096, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) = 0x7fb6b1155000</span></span>
<span class="line"><span>0.000047 access(&quot;/etc/ld.so.preload&quot;, R_OK) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>0.000119 open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><code>strace</code> 實用程序非常有助於理解 Linux 上的系統調用。要了解它的其它命令列標誌，請參考手冊頁和在線文檔。</p><hr>`,93)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/19/10/strace"},{default:i(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/19/10/strace",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/gkamathe"},{default:i(()=>[...s[5]||(s[5]=[e("Gaurav Kamathe",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const y=l(r,[["render",h]]);export{C as __pageData,y as default};
